import * as std from 'qjs:std';
interface Entry { word: string; count: number; }
const counts = new Map<string, number>();
for (const word of std.in.readAsString().toLowerCase().split(/[^a-z]+/)) {
  if (word) counts.set(word, (counts.get(word) ?? 0) + 1);
}
const entries: Entry[] = [...counts].map(([word, count]) => ({ word, count }));
entries.sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0));
for (const { word, count } of entries.slice(0, 3)) console.log(`${word} ${count}`);

function fib(n: number): bigint {
  let a = 0n, b = 1n;
  for (let i = 0; i < n; i++) [a, b] = [b, a + b];
  return a;
}
