import * as std from 'qjs:std';
enum Kind { Circle = 'circle', Square = 'square' }
abstract class Shape {
  constructor(public readonly kind: Kind) {}
  abstract area(): number;
}
class Circle extends Shape {
  constructor(private radius: number) { super(Kind.Circle); }
  area(): number { return Math.PI * this.radius * this.radius; }
}
class Square extends Shape {
  constructor(private side: number) { super(Kind.Square); }
  area(): number { return this.side * this.side; }
}
const shapes: Shape[] = std.in.readAsString().trim().split('\n').map((line: string) => {
  const [kind, size] = line.trim().split(/\s+/);
  return kind === Kind.Circle ? new Circle(Number(size)) : new Square(Number(size));
});
console.log(shapes.reduce((sum, shape) => sum + shape.area(), 0).toFixed(3));

import * as std from 'qjs:std';
class Stack<T> {
  private items: T[] = [];
  push(item: T): void { this.items.push(item); }
  pop(): T | undefined { return this.items.pop(); }
  get empty(): boolean { return this.items.length === 0; }
}
const pairs: Record<string, string> = { ')': '(', ']': '[', '}': '{' };
function balanced(line: string): boolean {
  const stack = new Stack<string>();
  for (const c of line) {
    if ('([{'.includes(c)) stack.push(c);
    else if (c in pairs && stack.pop() !== pairs[c]) return false;
  }
  return stack.empty;
}
for (const line of std.in.readAsString().split('\n')) if (line) console.log(balanced(line) ? 'yes' : 'no');

import * as std from 'qjs:std';
type Row = [number, number, number];
type Matrix = [Row, Row, Row];
const m = std.in.readAsString().trim().split('\n').map((line: string) => line.trim().split(/\s+/).map(Number)) as Matrix;
const det = (a: Matrix): number =>
  a[0][0] * (a[1][1] * a[2][2] - a[1][2] * a[2][1])
  - a[0][1] * (a[1][0] * a[2][2] - a[1][2] * a[2][0])
  + a[0][2] * (a[1][0] * a[2][1] - a[1][1] * a[2][0]);
console.log(det(m));

