import * as std from 'qjs:std';
const enum Unit { Point = 1 }
const WEIGHTS = { speed: 3, cost: 2, risk: 1 } as const satisfies Record<string, number>;
type Key = keyof typeof WEIGHTS;
let total = 0;
for (const part of std.in.readAsString().trim().split(';')) {
  const [key, value] = part.split('=');
  total += ((WEIGHTS as Record<string, number>)[key as Key] ?? 0) * Number(value) * Unit.Point;
}
console.log(total);

